@pytest.mark.asyncio
async def test_error_extract_input_conflicting_ocr() -> None:
    """extract force+disable OCR."""
    with pytest.raises(Exception):
        input = ExtractInput(
            bytes=Path("text/fake_text.txt").read_bytes(),
            config=FileExtractionConfig(disable_ocr=True, force_ocr=True),
            filename="fake_text.txt",
            kind=ExtractInputKind("bytes"),
            mime_type="text/plain",
        )
        config = ExtractionConfig.from_json('{"disable_ocr":true,"force_ocr":true}')
        await extract(input, config)


